#include <stdio.h>
#include <stdlib.h>

//function for calculating power of -1.
int  power(int q)
{
    int i,res=1;
    for(i=1;i<=q;i++)
    {
        res=-1*res;
    }
    return res;
}

int Determinant(int **mat,int n,int i,int j)
{
    static int q=-1;
    int sum=0;
//base cases.
    if(n==0)
    {
        return 0;
    }
    else if(n==1)
    {
        return mat[i][j];
    }
    else if(n==2)
    {
        return mat[i][j]*mat[i+1][j+1]-mat[i][j+1]*mat[i+1][j];
    }
//these are the three base cases.
    else
    {
        int s,t,x,y,**new;


    new=(int**)malloc(n*sizeof(int*));
    int a;
    for(a=0;a<n;a++)
    {
        new[a]=(int*)malloc(n*sizeof(int));
    }

        for(s=0;s<n;s++)
        {
            for(x=1;x<n;x++)
            {
                t=0;
                for(y=0;y<n;y++)
                {
                    if(y==s)
                    continue;
                    new[x-1][t]=mat[x][y];
                    t++;
                }
            }

  sum=sum+power(++q)*mat[i][j]*Determinant(new,n-1,i,j);
            return sum;
            //using recursion.
        }
    }
    return 0;
}


